
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_mohlyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_mohlyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.270563833208708e+00, -4.187053196138102e+00, -4.070116870903195e+00, -3.908316051089382e+00, -3.688272264918256e+00, -3.396455652181636e+00, -3.023527334869426e+00, -2.572813751221263e+00, -2.073485078800639e+00, -1.583735991694848e+00, -1.102979705952874e+00, -7.339703749089723e-01, -6.353831627747631e-01, -5.197476496942988e-01, -3.797977041226430e-01, -2.583177755942180e-01, -1.630201727241774e-01, -6.894305472055758e-02, -1.548253677231635e-02, -1.771135423821102e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


